18: How to make REST calls in PHP
19: Example of calling GET request
20: //next example will recieve all messages for specific conversation
21: $service_url = 'https://example.com/api/conversations/[CONV_CODE]/messages&apikey=[API_KEY]';
22: $curl = curl_init($service_url);
23: curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
24: $curl_response = curl_exec($curl);
25: if ($curl_response === false) {
26: $info = curl_getinfo($curl);
27: curl_close($curl);
28: die('error occured during curl exec. Additioanl info: ' . var_export($info));
29: }
30: curl_close($curl);
31: $decoded = json_decode($curl_response);
32: if (isset($decoded->response->status) && $decoded->response->status == 'ERROR') {
33: die('error occured: ' . $decoded->response->errormessage);
34: }
35: echo 'response ok!';
36: var_export($decoded->response);
37: Example of calling POST request
38: //next example will insert new conversation
39: $service_url = 'https://example.com/api/conversations';
40: $curl = curl_init($service_url);
41: $curl_post_data = array(
42: 'message' => 'test message',
43: 'useridentifier' => 'agent@example.com',
44: 'department' => 'departmentId001',
45: 'subject' => 'My first conversation',
46: 'recipient' => 'recipient@example.com',
47: 'apikey' => 'key001'
48: );
49: curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
50: curl_setopt($curl, CURLOPT_POST, true);
51: curl_setopt($curl, CURLOPT_POSTFIELDS, $curl_post_data);
52: $curl_response = curl_exec($curl);
53: if ($curl_response === false) {
54: $info = curl_getinfo($curl);
55: curl_close($curl);
56: die('error occured during curl exec. Additioanl info: ' . var_export($info));
57: }
58: curl_close($curl);
59: $decoded = json_decode($curl_response);
60: if (isset($decoded->response->status) && $decoded->response->status == 'ERROR') {
61: die('error occured: ' . $decoded->response->errormessage);
62: }
63: echo 'response ok!';
64: var_export($decoded->response);
65: Example of calling PUT request
66: //next eample will change status of specific conversation to resolve
67: $service_url = 'https://example.com/api/conversations/cid123/status';
68: $ch = curl_init($service_url);
69: curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
70: curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "PUT");
71: $data = array("status" => 'R');
72: curl_setopt($ch, CURLOPT_POSTFIELDS,http_build_query($data));
73: $response = curl_exec($ch);
74: if ($response === false) {
75: $info = curl_getinfo($ch);
76: curl_close($ch);
77: die('error occured during curl exec. Additioanl info: ' . var_export($info));
78: }
79: curl_close($ch);
80: $decoded = json_decode($response);
81: if (isset($decoded->response->status) && $decoded->response->status == 'ERROR') {
82: die('error occured: ' . $decoded->response->errormessage);
83: }
84: echo 'response ok!';
85: var_export($decoded->response);
